const courses=[
 {title:'Big 4 Auditor Financial Analyst',category:'Bisnis',image:1,teacher:'Jenna Ortega',job:'Senior Accountant di Gojek'},
 {title:'Strategi Pemasaran Digital',category:'Pemasaran',image:2,teacher:'Jenna Ortega',job:'Digital Marketing Specialist'},
 {title:'Dasar Desain untuk Pemula',category:'Desain',image:3,teacher:'Jenna Ortega',job:'UI/UX Designer'},
 {title:'Produktivitas dan Manajemen Waktu',category:'Pengembangan Diri',image:4,teacher:'Jenna Ortega',job:'Learning Facilitator'},
 {title:'Membangun Bisnis yang Berkelanjutan',category:'Bisnis',image:5,teacher:'Jenna Ortega',job:'Business Consultant'},
 {title:'Content Marketing yang Efektif',category:'Pemasaran',image:6,teacher:'Jenna Ortega',job:'Content Strategist'},
 {title:'Prinsip Desain Visual',category:'Desain',image:7,teacher:'Jenna Ortega',job:'Visual Designer'},
 {title:'Komunikasi untuk Dunia Kerja',category:'Pengembangan Diri',image:2,teacher:'Jenna Ortega',job:'Learning Facilitator'},
 {title:'Memahami Laporan Keuangan',category:'Bisnis',image:3,teacher:'Jenna Ortega',job:'Senior Accountant'}
];
let toastTimer;
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4500)}
function filter(category){const grid=document.getElementById('course-grid');if(!grid)return;document.querySelectorAll('.tab').forEach(el=>{const active=el.dataset.category===category;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1});grid.innerHTML=courses.map((course,i)=>({...course,id:i})).filter(course=>category==='Semua Kelas'||course.category===category).map(course=>`<button class="course" data-course="${course.id}" aria-label="Lihat course ${course.title}"><img class="course-image" src="assets/course-${course.image}.jpg" alt="Materi pembelajaran ${course.category}" loading="lazy" width="528" height="297"><h3>${course.title}</h3><p class="course-description">Mulai transformasi dengan instruktur profesional, materi praktis, dan harga yang terjangkau.</p><div class="teacher"><div class="teacher-icon" aria-hidden="true">JO</div><div><div class="teacher-name">${course.teacher}</div><div class="teacher-job">${course.job}</div></div></div><div class="course-bottom"><div aria-label="Rating 3,5 dari 5 berdasarkan 86 ulasan"><span class="stars" aria-hidden="true">★★★<span style="color:#ddd">★★</span></span><span class="rating">3.5 (86)</span></div><span class="price">Rp 300K</span></div></button>`).join('');grid.querySelectorAll('[data-course]').forEach(el=>el.addEventListener('click',()=>{const c=courses[Number(el.dataset.course)];document.getElementById('dialog-content').innerHTML=`<div class="eyebrow" style="color:#777">${c.category}</div><img class="dialog-image" src="assets/course-${c.image}.jpg" alt="Materi ${c.category}"><h2>${c.title}</h2><p class="muted">Belajar bersama ${c.teacher}. Materi praktis untuk mengembangkan keterampilanmu.</p><p class="price">Rp 300K</p><p class="demo-note">Contoh course untuk demo website. Video dan pembelian belum tersedia.</p>`;document.getElementById('course-dialog').showModal()}))}
filter('Semua Kelas');
document.querySelectorAll('[data-category]').forEach(el=>{el.addEventListener('click',()=>filter(el.dataset.category));el.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('.tab')];let i=tabs.indexOf(el);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;filter(tabs[i].dataset.category);tabs[i].focus()})});
document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>filter(el.dataset.filter)));
document.querySelector('.menu-button')?.addEventListener('click',e=>{const open=document.getElementById('navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});
document.querySelectorAll('.eye').forEach(el=>el.addEventListener('click',()=>{const input=el.previousElementSibling;const show=input.type==='password';input.type=show?'text':'password';el.setAttribute('aria-label',show?'Sembunyikan kata sandi':'Tampilkan kata sandi');el.setAttribute('aria-pressed',String(show))}));
document.getElementById('auth-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;const feedback=document.getElementById('auth-feedback');feedback.classList.remove('error');if(form.dataset.mode==='register'&&form.elements.password.value!==form.elements.confirm.value){feedback.textContent='Konfirmasi kata sandi harus sama dengan kata sandi.';feedback.classList.add('error');form.elements.confirm.focus();return}feedback.textContent=form.dataset.mode==='register'?'Validasi berhasil. Membuka halaman login demo…':'Validasi berhasil. Membuka beranda demo…';form.querySelector('[type=submit]').disabled=true;setTimeout(()=>{location.href=form.dataset.mode==='register'?'login.html':'index.html'},800)});
document.getElementById('google-button')?.addEventListener('click',()=>toast('Login Google belum terhubung pada versi demo ini.'));
document.getElementById('forgot-password')?.addEventListener('click',e=>{e.preventDefault();document.getElementById('forgot-dialog').showModal()});
document.getElementById('reset-form')?.addEventListener('submit',e=>{e.preventDefault();document.getElementById('reset-feedback').textContent='Form demo berhasil divalidasi. Email pemulihan tidak dikirim.'});
document.querySelectorAll('.dialog-close').forEach(el=>el.addEventListener('click',()=>el.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(el=>el.addEventListener('click',e=>{if(e.target===el){const r=el.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el.close()}}));
document.getElementById('newsletter-form')?.addEventListener('submit',e=>{e.preventDefault();document.getElementById('newsletter-feedback').textContent='Terima kasih! Form demo berhasil divalidasi; email belum disimpan.';e.currentTarget.reset()});
document.querySelectorAll('[data-info]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();toast(`${el.dataset.info}: halaman ini belum tersedia pada MVP.`)}));
if(matchMedia('(max-width:600px)').matches)document.querySelectorAll('.footer details').forEach(el=>el.open=false);
